#!/usr/bin/env node
'use strict';

/**
 * Regenerates the TypeScript copy of the cad-engine assembly JSON Schema. The canonical file is
 * cad-engine/contract/assembly.schema.json (the backend Docker build context cannot reach it). Never hand-edit the
 * generated file; a spec fails when it drifts.
 * Run from backend/:  npm run cad:sync-contract
 */

const fs = require('fs');
const path = require('path');

const source = path.resolve(__dirname, '../../cad-engine/contract/assembly.schema.json');
const out = path.resolve(__dirname, '../src/modules/cad-uploads/assembly-schema.generated.ts');

function render() {
  return [
    '// GENERATED by scripts/sync-cad-contract.js from cad-engine/contract/assembly.schema.json. Do not edit.',
    `export const ASSEMBLY_SCHEMA = ${JSON.stringify(JSON.parse(fs.readFileSync(source, 'utf8')), null, 2)} as const;`,
    '',
  ].join('\n');
}

if (require.main === module) {
  fs.writeFileSync(out, render());
  console.log(`wrote ${path.relative(process.cwd(), out)}`);
}

module.exports = { render, out };
